USE storms;

ON DUPLICATE KEY UPDATE title=VALUES(title),heroImage=VALUES(heroImage),mapAddress=VALUES(mapAddress),latitude=VALUES(latitude),longitude=VALUES(longitude);

ON DUPLICATE KEY UPDATE title=VALUES(title),heroImage=VALUES(heroImage),titleEn=VALUES(titleEn);

ON DUPLICATE KEY UPDATE title=VALUES(title),heroImage=VALUES(heroImage),titleEn=VALUES(titleEn);


SELECT p.id, CASE p.slug WHEN 'dobracina-21' THEN '/images/projects/dobracina-21/hero-v2.png' WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-blue-hour.webp' WHEN 'aurora-sky-villa' THEN '/images/projects/aurora-sky-villa/hero-v2.png' WHEN 'nocturne-private-spa' THEN '/images/projects/nocturne-private-spa/hero-v2.png' ELSE CONCAT('/images/projects/',p.slug,'/hero.webp') END, CONCAT(p.title,' — enterijer'),'INTERIOR',1 FROM projects p WHERE p.id IN (1,2,3,5,6,7,8,9,10)
UNION ALL SELECT p.id, CASE p.slug WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-dining.webp' WHEN 'aurora-sky-villa' THEN '/images/projects/aurora-sky-villa/gallery-v2.png' WHEN 'nocturne-private-spa' THEN '/images/projects/nocturne-private-spa/gallery-v2.png' END, CONCAT(p.title,' — galerija'),'INTERIOR',2 FROM projects p WHERE p.id IN (3,9,10)
UNION ALL SELECT p.id, CASE p.slug WHEN 'dobracina-21' THEN '/images/projects/dobracina-21/plan-2d-v2.png' WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-plan-2d.webp' ELSE CONCAT('/images/projects/',p.slug,'/plan-2d.webp') END, CONCAT(p.title,' — 2D osnova'),'FLOOR_PLAN',3 FROM projects p WHERE p.id IN (1,2,3,5,6,7,8,9,10)
UNION ALL SELECT p.id, CASE p.slug WHEN 'dobracina-21' THEN '/images/projects/dobracina-21/plan-3d-v2.png' WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-plan-3d.webp' WHEN 'aurora-sky-villa' THEN '/images/projects/aurora-sky-villa/plan-3d-v2.png' WHEN 'nocturne-private-spa' THEN '/images/projects/nocturne-private-spa/plan-3d-v2.png' WHEN 'atrium-works' THEN '/images/projects/atrium-works/plan-3d-v2.png' ELSE CONCAT('/images/projects/',p.slug,'/plan-3d.webp') END, CONCAT(p.title,' — 3D prikaz'),'FLOOR_PLAN',4 FROM projects p WHERE p.id IN (1,2,3,5,6,7,8,9,10);

SELECT p.id,p.heroImage,p.title,'EXTERIOR',1 FROM projects p WHERE p.id IN (11,12,13);

SELECT p.id,'Arhitektonska 2D osnova',CASE p.slug WHEN 'dobracina-21' THEN '/images/projects/dobracina-21/plan-2d-v2.png' WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-plan-2d.webp' ELSE CONCAT('/images/projects/',p.slug,'/plan-2d.webp') END,1 FROM projects p WHERE p.id IN (1,2,3,5,6,7,8,9,10)
UNION ALL SELECT p.id,'3D prostorni prikaz',CASE p.slug WHEN 'dobracina-21' THEN '/images/projects/dobracina-21/plan-3d-v2.png' WHEN 'skyline-penthouse' THEN '/images/lux/penthouse-plan-3d.webp' WHEN 'aurora-sky-villa' THEN '/images/projects/aurora-sky-villa/plan-3d-v2.png' WHEN 'nocturne-private-spa' THEN '/images/projects/nocturne-private-spa/plan-3d-v2.png' WHEN 'atrium-works' THEN '/images/projects/atrium-works/plan-3d-v2.png' ELSE CONCAT('/images/projects/',p.slug,'/plan-3d.webp') END,2 FROM projects p WHERE p.id IN (1,2,3,5,6,7,8,9,10);


ON DUPLICATE KEY UPDATE settingValue=VALUES(settingValue);
